  "kasse.vorschlagenFrage": {
    de: "{betrag} an {empfaenger} vorschlagen?\n\nDie Miete für den Vorschlag ({miete}) und die Netzgebühr zahlt {zahler}. Die Miete geht beim Abschließen in den Tresor, nicht zurück zu dir. Empfänger und Betrag stehen öffentlich auf der Kette.",
    en: "Propose {betrag} to {empfaenger}?\n\nThe rent for the proposal ({miete}) and the network fee are paid by {zahler}. The rent goes to the vault when the proposal is closed, not back to you. Recipient and amount are public on the chain.",
  },
  "kasse.dafuerFrage": { de: "Für Nr. {nr} stimmen? So steht es auf der Kette: {betrag} an {empfaenger}.\n\nDie Netzgebühr zahlt {zahler}.", en: "Vote for no. {nr}? This is what the chain says: {betrag} to {empfaenger}.\n\nThe network fee is paid by {zahler}." },
  "kasse.dagegenFrage": { de: "Gegen Nr. {nr} stimmen? So steht es auf der Kette: {betrag} an {empfaenger}.\n\nDie Netzgebühr zahlt {zahler}.", en: "Vote against no. {nr}? This is what the chain says: {betrag} to {empfaenger}.\n\nThe network fee is paid by {zahler}." },
  "kasse.ausfuehrenFrage": {
    de: "Nr. {nr} jetzt auszahlen? So steht es auf der Kette: {betrag} an {empfaenger}. Im selben Zug wird der Vorschlag abgeschlossen, seine Miete geht in den Tresor.\n\nDie Netzgebühr zahlt {zahler}.",
    en: "Pay out no. {nr} now? This is what the chain says: {betrag} to {empfaenger}. In the same step the proposal is closed and its rent goes to the vault.\n\nThe network fee is paid by {zahler}.",
  },
  "kasse.abschliessenFrage": { de: "Nr. {nr} abschließen? Seine Miete geht in den Tresor.\n\nDie Netzgebühr zahlt {zahler}.", en: "Close no. {nr}? Its rent goes to the vault.\n\nThe network fee is paid by {zahler}." },
  "kasse.zahlerVerbundenOhne": { de: "Auf der Kette ist diese Adresse dann mit der Kasse verbunden.", en: "On the chain this address is then linked to the treasury." },
  "kasse.vorgeschlagen": { de: "Auszahlung Nr. {nr} vorgeschlagen.", en: "Payout no. {nr} proposed." },
  "kasse.abgestimmt": { de: "Stimme zu Nr. {nr} gesendet.", en: "Vote on no. {nr} sent." },
  "kasse.ausgezahlt": { de: "Nr. {nr} ausgezahlt.", en: "No. {nr} paid out." },
  "kasse.abgeschlossen": { de: "Nr. {nr} abgeschlossen.", en: "No. {nr} closed." },
  "kasse.nurEingebaut": { de: "Vorschlagen, abstimmen und auszahlen gehen nur mit der Adresse, die du dem Raum für die Kasse genannt hast – aus der eingebauten SOL-Wallet bei offenem Tresor oder aus der verbundenen Wallet mit genau dieser Adresse.", en: "Proposing, voting and paying out only work with the address you gave the room for the treasury – from the built-in SOL wallet with an open vault or from the connected wallet with exactly this address." },
  "kasse.verbundenUnterschreibt": { de: "Unterschreiben wird deine verbundene Wallet. Gesendet wird nur an Devnet, über deine eigenen Endpunkte – nicht über die Wallet.", en: "Your connected wallet will sign. It is sent only to devnet, through your own endpoints – not through the wallet." },
  "kasse.nichtAuszahlen": { de: "Mit dieser Kasse arbeitet die App nicht: Es gibt sie auf Devnet nicht, oder sie hat eine Form, die die App nicht anlegt.", en: "The app does not work with this treasury: it does not exist on devnet, or it has a form the app does not create." },
